from taf.internal.aliasing import aliasing_scope
from taf.nms.nsp.nfmp.facade import NfmpConnectionFacade


class nfmp(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    ROBOT_LISTENER_API_VERSION = 2
    lookup_handler, store = aliasing_scope(name=__name__, lookup_arg='connection', lookup_type=NfmpConnectionFacade)

    def setup(self, ip, username, password, port=8443, nfmp_version=19, alias='default'):
        """
        Connect and authrorize to NFMP

        :param str ip: ip_address: ie. "10.108.141.24" or "[2a00:8a00:6000:607c::fd04]"
        :param str username: username to authenticate to NFMP
        :param str password: password to authenticate to NFMP
        :param int port: ie. 8443
        :param nfmp_version: version of NFMP, ie. 18, "18A", 19, "19A"
        :type nfmp_version: int or str
        :param str alias: Name of returned connection. It not provided, this connection becomes default.

        :return: NfmpConnectionFacade instance
        :rtype: NfmpConnectionFacade
        """
        connection = NfmpConnectionFacade(ip, username, password, port, nfmp_version)
        self.store.add(connection, alias)
        return connection

    @lookup_handler.implicit_lookup
    def reset_mrbts(self, site_id, connection=None):
        connection.reset_mrbts(site_id)

    @lookup_handler.implicit_lookup
    def change_nrcell_administrative_state(self, site_id, state, connection=None):
        """
        Keyword to change administrative state of NRCELL with specified site id

        :param str site_id: id of site(MRBTS), ie. MRBTS-1900
        :param int state: ie. 0 is "Locked", 1 is "Unlocked" and 2 is "Shutting Down"
        :param Optional[str] connection: NfmpConnectionFacade instance or if used, string name is alias
        :return: NRCELL info
        :rtype: dict
        :raise: NoSuchNodeError
        """
        return connection.change_nrcell_administrative_state(site_id, state)

    @lookup_handler.implicit_lookup
    def get_alarms(self, connection=None):
        """
        Keyword to get alarms by using XML api.

        :param Optional[str] connection: NfmpConnectionFacade instance or if used, string name is alias
        :return: alarms info
        :rtype: list, list of dicts
        """
        return connection.get_alarms()

    @lookup_handler.implicit_lookup
    def get_mrbts_component_general_info(self, site_id, connection=None):
        """
        Keyword to get specific mrbts general info by using XML api.

        :param str site_id: id of site(MRBTS), ie. MRBTS-1900
        :param Optional[str] connection: NfmpConnectionFacade instance or if used, string name is alias
        :return: mrbts general info
        :rtype: dict
        """
        return connection.get_mrbts_component_general_info(site_id)

    @lookup_handler.implicit_lookup
    def get_hw_component_general_info(self, site_id, module_id=1, connection=None):
        """
        Keyword to get HW component general info by using XML api.

        :param str site_id: id of site(MRBTS), ie. MRBTS-1900
        :param Optional[int] module_id: id number of HW, default 1
        :param Optional[str] connection: NfmpConnectionFacade instance or if used, string name is alias
        :return: HW component general info
        :rtype: dict
        """
        return connection.get_hw_component_general_info(site_id, module_id)

