    @lookup_handler.implicit_lookup
    def set_vnf_to_active(self, bts_id, connection=None):
        """
        Sets given VNF state to active.

        :param str bts_id: ie. "MRBTS-1900"
        :param Optional[str] connection: NfmpConnectionFacade instance or if used, string name is alias
        :return: None
        """
        connection.set_vnf_to_active(bts_id=bts_id)

    @lookup_handler.implicit_lookup
    def set_vnf_to_standby(self, bts_id, connection=None):
        """
        Sets given VNF state to standby.

        :param str bts_id: ie. "MRBTS-1900"
        :param Optional[str] connection: NfmpConnectionFacade instance or if used, string name is alias
        :return: None
        """
        connection.set_vnf_to_standby(bts_id=bts_id)

    @lookup_handler.implicit_lookup
    def update_from_peer_node(self, bts_id, connection=None):
        """
        Updates configuration of a given node from an active node.

        :param str bts_id: ie. "MRBTS-1900"
        :param Optional[str] connection: NfmpConnectionFacade instance or if used, string name is alias
        :return: None
        """
        connection.update_from_peer_node(bts_id=bts_id)

    def teardown(self, alias):
        self.store.remove(alias)
